def dehydrate_time(value):
    """
    Dehydrator for `time` values.
    Convert a datetime.time instance to its ISO 8601 string representation.
    Accepts ``None`` and returns ``None``. Raises ``TypeError`` for invalid types.
    """
    import datetime
    if value is None:
        return None
    if not isinstance(value, datetime.time):
        raise TypeError(f"dehydrate_time: Expected datetime.time, got {type(value).__name__}")
    try:
        # .isoformat() handles microseconds and UTC offset if present
        return value.isoformat()
    except Exception as exc:
        raise ValueError(f"dehydrate_time: Failed to convert time value {value!r}") from exc

