    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple of integers or None")

    # Retrieve the internal mapping of protocol handlers; default to empty
    try:
        handlers_map = getattr(cls, "_protocol_handlers", {})
        if not isinstance(handlers_map, dict):
            # If the attribute exists but is not a dict, ignore it
            handlers_map = {}
