    try:
        record = self._record
    except AttributeError as exc:
        raise AttributeError('The object does not contain a _record attribute') from exc

    if not isinstance(record, dict):
        raise TypeError('Record is expected to be a dict-like object')

    # Convert to list of items to preserve order
    items = list(record.items())

    # If no keys are supplied, return all values
