@classmethod
def _reset_logging(cls):
    """
    Reset logging configuration to its default state.
    """
    try:
        if not isinstance(cls, type):
            raise TypeError(f"Expected class type for cls, got {type(cls)}")
        root = logging.getLogger()
        for handler in root.handlers[:]:
            root.removeHandler(handler)
        root.setLevel(logging.WARNING)
        logging.basicConfig()
    except Exception as exc:
        try:
            logging.getLogger().error("Error resetting logging: %s", exc)
        except Exception:
            raise

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent."""
    # Ensure we have a list
    try:
        cls_list = list(classes)
    except TypeError:
        raise TypeError("Expected an iterable of classes") from None

    # Validate that all items are classes
    for cls in cls_list:
        if not isinstance(cls, type):
            raise TypeError(f"Item {cls!r} is not a class")

    # Build the minimal set: keep classes that are not superclasses of any other
    minimal = []
    for candidate in cls_list:
        # Determine if this candidate is a superclass of any other class in the list
        is_super = False
        for other in cls_list:
            if other is candidate:
                continue
            try:
                if issubclass(other, candidate):
                    is_super = True
                    break
