def _should_attempt_c_optimizations():
    """
    Return a true value if we should attempt to use the C optimizations.
    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    try:
        import sys
        import os
    except Exception:
        # If imports fail, we cannot reliably determine environment, default to False
        return False
    # Check for PyPy
    if hasattr(sys, "pypy_version_info"):
        return False
    # Check PURE_PYTHON environment variable
    try:
        pure_python_env = os.getenv("PURE_PYTHON")
    except Exception:
        pure_python_env = None
    if pure_python_env:
        pure_python_env = pure_python_env.strip().lower()
        if pure_python_env in {"1", "true", "t", "yes", "y", "on"}:
            return False
    return True

