    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Validate input
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("both 'd1' and 'd2' must be dictionaries")
    if not isinstance(level, int):
        raise TypeError("'level' must be an integer")

    def _diff(sub_d1, sub_d2, lvl):
        """
        Recursive helper to compute the difference between two dictionaries
        up to a specified recursion depth.
        """
        # If recursion depth limit reached, do not examine deeper
        if lvl == 0:
            return {}

        result = {}
        for key, val1 in sub_d1.items():
            if key not in sub_d2:
                # Key missing in sub_d2 → include it
                result[key] = val1
            else:
                val2 = sub_d2[key]
                # If both values are dictionaries, recurse
                if isinstance(val1, dict) and isinstance(val2, dict):
                    new_lvl = lvl - 1 if lvl > 0 else lvl  # preserve -1 for infinite
                    diff_sub = _diff(val1, val2, new_lvl)
                    if diff_sub:
                        result[key] = diff_sub
                else:
                    # Include if values differ
                    if val1 != val2:
                        result[key] = val1
        return result

    try:
        return _diff(d1, d2, level)
    except RecursionError as exc:
        # In case of pathological cyclic structures we keep behaviour sane
        raise ValueError("Maximum recursion depth exceeded while computing difference") from exc

def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Validate weight
    try:
        weight = float(weight)
    except Exception:
        # non‑numeric weight: ignore
        return

    # Prepare coordinate tuple
    if isinstance(coord, (int, float)):
        coord = (coord,)
    else:
        try:
            coord = tuple(coord)
        except Exception:
            # Cannot convert to tuple: ignore
            return

    # Check dimensionality
    try:
        ndim = len(self.edges)
    except Exception:
        # Histogram edges not set: ignore
        return
    if len(coord) != ndim:
        # Wrong dimensionality: ignore
        return

    # Compute bin indices
    indices = []
    for d, c in enumerate(coord):
        edges_d = self.edges[d]
        # Basic numeric check
        try:
            c = float(c)
        except Exception:
            # Non‑numeric coordinate: ignore
            return

        # Skip if coordinate outside edges
        if c < edges_d[0] or c >= edges_d[-1]:
            return

        # Find bin index
        # Use numpy.searchsorted if available, otherwise fallback to bisect
        try:
            # If numpy is available in the instance namespace
            idx = np.searchsorted(edges_d, c, side='right') - 1
        except NameError:
            import bisect
            idx = bisect.bisect_right(edges_d, c) - 1

        if idx < 0 or idx >= len(edges_d) - 1:
            # Should not happen because of edge check, but guard
            return
        indices.append(idx)

    # Increment histogram bin
    try:
        self.data[tuple(indices)] += weight
    except Exception:
        # Any error updating the data array: ignore
        return

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Recursively update a partial ``last_applied_manifest`` list with the
    values observed in the Kubernetes API response.  The function walks the
    ``response`` list, ensuring that ``last_applied_manifest`` has a
    corresponding element for each index.  For each element that does not
    yet exist in ``last_applied_manifest`` an empty container is created
    (dict or list) based on the provided ``observer_schema``.  If an
    element exists, nested structures are updated using the helper
    functions :func:`update_last_applied_manifest_dict_from_resp` and
    :func:`update_last_applied_manifest_list_from_resp`.

    The update is performed *in place* and the modified ``last_applied_manifest``
    object is returned for convenience.

    Args:
        last_applied_manifest (list): The manifest list being updated.
        observer_schema (dict or list): The schema describing the expected
            structure of list items.  If it is a dict, the key ``items``
            (containing a schema) is used to infer the type of each item.
        response (list): Partial Kubernetes response list containing the
            values to merge.

    Returns:
        list: The updated ``last_applied_manifest``.
    """
    if not isinstance(last_applied_manifest, list):
        raise TypeError("`last_applied_manifest` must be a list")
    if not isinstance(response, list):
        raise TypeError("`response` must be a list")

    # Helper to determine the initial type for an item based on schema
    def _default_for_schema(schema):
        if isinstance(schema, dict):
            # Items schema may be under 'items' key
            items = schema.get("items") or schema
            t = items.get("type")
            if t == "list":
                return []
            if t == "dict" or t == "object":
                return {}
        return {}

    for idx, resp_item in enumerate(response):
        # Grow the target list to accommodate new indices
        while len(last_applied_manifest) <= idx:
            last_applied_manifest.append(None)

        current_item = last_applied_manifest[idx]
        # If the slot is empty, create an appropriate container
        if current_item is None:
            last_applied_manifest[idx] = _default_for_schema(observer_schema)
            current_item = last_applied_manifest[idx]

        # If both current and response items are dicts or lists, recurse
        if isinstance(current_item, dict) and isinstance(resp_item, dict):
            try:
                update_last_applied_manifest_dict_from_resp(
                    current_item, observer_schema, resp_item
                )
            except Exception:
                # If the helper fails, fall back to direct overwrite
                last_applied_manifest[idx] = resp_item
        elif isinstance(current_item, list) and isinstance(resp_item, list):
            try:
                update_last_applied_manifest_list_from_resp(
                    current_item, observer_schema, resp_item
                )
            except Exception:
                last_applied_manifest[idx] = resp_item
        else:
            # Primitive values: prefer existing value if truthy, otherwise
            # update with the response value.
            if not current_item:
                last_applied_manifest[idx] = resp_item

    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response
        TypeError: If inputs are not of expected types.

    This function goes through all observed fields, and initializes their value in
    last_applied_manifest if they are not yet present.

    """
    if not isinstance(last_applied_manifest, dict):
        raise TypeError(
            f"last_applied_manifest must be a dict, got {type(last_applied_manifest).__name__}"
        )
    if not isinstance(observer_schema, dict):
        raise TypeError(
            f"observer_schema must be a dict, got {type(observer_schema).__name__}"
        )
    if not isinstance(response, dict):
        raise TypeError(
            f"response must be a dict, got {type(response).__name__}"
        )

    for key, sub_schema in observer_schema.items():
        if key not in response:
            raise KeyError(
                f"Observed field '{key}' not present in the Kubernetes response."
            )

        # Ensure the nested structure for dicts
        if isinstance(sub_schema, dict):
            # Initialize nested dict if needed
            if key not in last_applied_manifest or not isinstance(
                last_applied_manifest[key], dict
            ):
                last_applied_manifest[key] = {}
            # Recurse into nested objects
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], sub_schema, response[key]
            )
        else:
            # Leaf node: set value if not already present
            if key not in last_applied_manifest:
                last_applied_manifest[key] = response[key]
    return last_applied_manifest

def validate(self, path):
    """Validate OCFL object at path or pyfs root.
    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        import os
        import json

        if path is None:
            return False

        # Convert pathlib.Path or similar to string
        if not isinstance(path, str):
            try:
                path = str(path)
            except Exception:
                return False

        # Path must exist and be a directory
        if not os.path.isdir(path):
            return False

        # Minimal OCFL repository checks:
        #   * Presence of a config file: rc should contain either ocfl-repo.json or ocfl.json
        #   * Or presence of a version directory (e.g., v1, v2, etc.)
        repo_config_files = ["ocfl-repo.json", "ocfl.json"]
        for cfg_file in repo_config_files:
            cfg_path = os.path.join(path, cfg_file)
            if os.path.isfile(cfg_path):
                # Attempt to parse JSON to ensure it's syntactically correct
                try:
                    with open(cfg_path, "r", encoding="utf-8") as f:
                        json.load(f)
                except Exception:
                    # If config file can't be parsed, treat as invalid
                    continue
                return True

        # Fallback: look for a directory that looks like a version directory
        # Versions are typically named "v1", "v2", ...
        try:
            for entry in os.listdir(path):
                entry_path = os.path.join(path, entry)
                if os.path.isdir(entry_path) and entry.lower().startswith("v"):
                    return True
        except Exception:
            pass

        # If we reach here, none of the simple checks passed
        return False
    except Exception:
        # In case of any unexpected runtime error, consider validation failed
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    try:
        status = getattr(self, 'status', None)
        if status is None:
            return f"{prefix}NO_STATUS"
        return f"{prefix}{status}"
    except Exception as exc:
        return f"{prefix}ERROR: {exc}"

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    try:
        # Basic structure check
        if not isinstance(inventory, dict):
            return False

        # Determine the spec_version to use
        spec_version = getattr(self, "spec_version", None)
        if extract_spec_version:
            type_val = inventory.get("type")
            if type_val:
                # Optional mapping from type to version
                type_to_version = getattr(self, "type_to_version", {})
                spec_version = type_to_version.get(type_val, spec_version)

        # If we still don't have a spec_version, validation fails
        if not isinstance(spec_version, str):
            return False

        # Example validation logic for known spec versions
        if spec_version == "1.0":
            # Version 1.0 expects a 'name' field and an 'items' list
            if "name" not in inventory or not isinstance(inventory["name"], str):
                return False
            items = inventory.get("items")
            if not isinstance(items, list):
                return False
            for it in items:
                if not isinstance(it, dict):
                    return False
                # Each item must have 'item_name' and 'value' keys
                if "item_name" not in it or "value" not in it:
                    return False

        elif spec_version == "0.9":
            # Version 0.9 expects an 'id' field that is an integer
            if "id" not in inventory or not isinstance(inventory["id"], int):
                return False

        else:
            # Unsupported or unrecognized spec_version
            return False

        return True
    except Exception:
        # Any unexpected error during validation results in an invalid inventory
        return False

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    try:
        # Ensure prior is an InventoryValidator (basic duck typing)
        if not hasattr(prior, 'inventory'):
            raise ValueError('prior object lacks an inventory attribute')
        if not hasattr(self, 'inventory'):
            raise ValueError('self object lacks an inventory attribute')

        current_inv = self.inventory
        prior_inv = prior.inventory

        # Compare version numbers if they exist
        current_version = getattr(current_inv, 'version', None)
        prior_version = getattr(prior_inv, 'version', None)
        if current_version is None or prior_version is None:
            raise ValueError('Inventories missing version information')

        if current_version <= prior_version:
            raise ValueError('Current inventory version must be greater than prior version')

        # Ensure every item/key in the prior inventory appears in the current inventory
        if hasattr(prior_inv, 'keys'):
            # Assume prior_inv behaves like a dict
            for key in prior_inv.keys():
                if key not in current_inv:
                    raise ValueError(f'Key "{key}" from prior inventory not found in current inventory')
                # Optional: check that types are consistent
                if type(prior_inv[key]) != type(current_inv[key]):
                    raise ValueError(f'Type mismatch for key "{key}": prior {type(prior_inv[key])}, current {type(current_inv[key])}')
        else:
            # If prior_inv is not dict-like, attempt iterable comparison
            try:
                for item in prior_inv:
                    if item not in current_inv:
                        raise ValueError(f'Item "{item}" from prior inventory not found in current inventory')
            except TypeError:
                # Fallback: just compare hashable collections if possible
                pass

        return True
    except Exception as exc:
        raise ValueError(f'Invalid prior version: {exc}')

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Ensure we can work with the input
    if inventory is None:
        return {}
    if not isinstance(version, (str, int)):
        raise ValueError(f"Invalid version type: {type(version)}")

    result = {}

    # Helper to add a mapping
    def _add_mapping(logical_path, files):
        try:
            if logical_path is None:
                return
            files_set = set(files) if files is not None else set()
            if logical_path in result:
                result[logical_path].update(files_set)
            else:
                result[logical_path] = files_set
        except Exception:
            # Silently ignore invalid entries
            pass

    # Case 1: inventory is already the desired map
    if isinstance(inventory, dict):
        # Check if the dict keys look like logical paths (string) and values are iterable
        if all(isinstance(v, (set, list, tuple, frozenset)) for v in inventory.values()):
            return {k: set(v) for k, v in inventory.items()}

    # Case 2: inventory is a mapping from logical paths to metadata
    if isinstance(inventory, dict):
        for key, value in inventory.items():
            # If key looks like a logical path and value contains files
            if isinstance(key, str) and isinstance(value, dict):
                try:
                    v = value.get('version')
                    if v == version or (isinstance(v, list) and version in v):
                        # Prefer 'content_files' then 'files'
                        files = value.get('content_files') or value.get('files')
                        _add_mapping(key, files)
                except Exception:
                    continue
            # If key looks like logical path and value is a list/iterable
            elif isinstance(key, str) and isinstance(value, (list, set, tuple)):
                _add_mapping(key, value)
        return result

    # Case 3: inventory is a list/iterable of dicts
    try:
        iter(inventory)
    except TypeError:
        # Not iterable, return empty
        return result

    for item in inventory:
        if not isinstance(item, dict):
            continue
        try:
            v = item.get('version')
            if v == version or (isinstance(v, list) and version in v):
                logical_path = item.get('logical_path')
                files = item.get('content_files') or item.get('files')
                _add_mapping(logical_path, files)
        except Exception:
            continue

    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Prepare error collection
    if not hasattr(self, "errors"):
        self.errors = []
    valid = True

    # Convert manifest to a set for quick lookup
    try:
        manifest_set = set(manifest_files)
    except Exception:
        self.errors.append("Manifest files must be iterable.")
        return False

    # Check type of the fixity block
    if isinstance(fixity, dict):
        items = fixity.items()
    elif isinstance(fixity, list):
        items = enumerate(fixity)
    else:
        self.errors.append("Fixity block must be a dict or a list.")
        return False

    # Validate each entry
    for key, entry in items:
        if isinstance(fixity, dict):
            file_path, info = key, entry
        else:
            file_path = entry.get("file") if isinstance(entry, dict) else None
            info = entry

        # Basic structure checks
        if not isinstance(info, dict):
            self.errors.append(f"Fixity entry for '{file_path}' must be a dictionary.")
            valid = False
            continue

        # Check required keys
        if "checksum" not in info:
            self.errors.append(f"Missing 'checksum' in fixity entry for '{file_path}'.")
            valid = False

        # Verify referenced file exists in the manifest
        if isinstance(file_path, str):
            if file_path not in manifest_set:
                self.errors.append(
                    f"File '{file_path}' referenced in fixity block is not in the manifest."
                )
                valid = False
        else:
            self.errors.append(
                f"Invalid file reference in fixity entry: {info}. "
                "Expected a string path."
            )
            valid = False

    return valid

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        Zip file path.

    Returns
    -------
    dict
        Mapping from XML basename (without extension) to a list of file paths
        inside the zip that share that basename.
    """
    import os
    import zipfile

    # Validate input type
    if not isinstance(zip_path, str):
        raise TypeError(f"zip_path must be a str, got {type(zip_path).__name__}")

    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"zip file {zip_path!r} does not exist")

    packages = {}

    try:
        with zipfile.ZipFile(zip_path, "r") as zf:
            # First find all XML files and collect their basenames
            xml_basenames = set()
            for name in zf.namelist():
                # Skip directories
                if name.endswith("/"):
                    continue
                basename, ext = os.path.splitext(os.path.basename(name))
                if ext.lower() == ".xml":
                    xml_basenames.add(basename)

            # Initialize dict with xml files
            for name in zf.namelist():
                if name.endswith("/"):
                    continue
                basename, ext = os.path.splitext(os.path.basename(name))
                if basename in xml_basenames:
                    packages.setdefault(basename, []).append(name)

            # Add other files that share a basename with an xml file
            for name in zf.namelist():
                if name.endswith("/"):
                    continue
                basename, ext = os.path.splitext(os.path.basename(name))
                if basename in xml_basenames:
                    # Avoid duplication of xml files already added
                    if name not in packages[basename]:
                        packages[basename].append(name)

    except zipfile.BadZipFile as exc:
        raise zipfile.BadZipFile(f"Cannot read zip file {zip_path!r}: {exc}") from exc
    except Exception as exc:
        # Generic exception handling to avoid crashing
        raise RuntimeError(f"Error while processing zip file {zip_path!r}: {exc}") from exc

    return packages

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`.
    """
    try:
        if not isinstance(content, str):
            raise TypeError("content must be a string")
        return content.replace('w:st="', 'w-st="')
    except Exception as e:
        raise ValueError(f"Error processing content: {e}") from e

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    # Validate inputs
    if node is None or not pubdate_xpaths:
        return None
    if not hasattr(node, "xpath"):
        # Node does not support XPath evaluation
        return None
    for xpath in pubdate_xpaths:
        try:
            # Attempt to evaluate the XPath
            matches = node.xpath(xpath)
            if matches:
                # Return the first match found
                return matches[0]
        except Exception:
            # If the XPath is invalid or evaluation fails, skip to the next
            continue
    # No match found in the list of XPaths
    return None

def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    import re
    try:
        if issue is None:
            return (None, None)

        # Obtém o texto contido no elemento, caso seja um objeto com atributo .text
        text = issue.text if hasattr(issue, 'text') else str(issue)
        if not text:
            return (None, None)

        text = text.strip()

        # Padrão para extração do número ou intervalo de números no início da string
        number_match = re.match(r'^\s*(\d+)(?:-(\d+))?', text)
        number = None
        if number_match:
            if number_match.group(2):
                number = f'{number_match.group(1)}-{number_match.group(2)}'
            else:
                number = number_match.group(1)

        # Padrões para identificação de suplementação (Suppl, Spe, etc.)
        sup_pattern = r'(suppl|spe|s\.?uppl|supp|suppl\.?|spe\.?)\s*\.?\s*(\d+)?'
        sup_match = re.search(sup_pattern, text, re.I)

        supplement = None
        if sup_match:
            if sup_match.group(2):
                try:
                    supplement = int(sup_match.group(2))
                except (TypeError, ValueError):
                    supplement = None
            else:
                # Indica presença de suplemento sem número
                supplement = None

        return (number, supplement)

    except Exception:
        # Em caso de qualquer erro inesperado, devolve valores nulos
        return (None, None)

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    if hook is None:
        raise ValueError("Hook must not be None.")
    # Ensure the registry dict exists on the instance
    if not hasattr(self, "_handlers"):
        self._handlers = {}
    # Get or create the list for this hook
    handlers = self._handlers.setdefault(hook, [])
    def decorator(func):
        if not callable(func):
            raise TypeError(f"Listener for hook {hook!r} must be callable.")
        # Avoid duplicate registrations
        if func not in handlers:
            handlers.append(func)
        return func
    return decorator

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    def wrapped(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        # In Python 2, convert unicode output to bytestrings
        if sys.version_info[0] == 2:
            try:
                # 'unicode' is only defined in Python 2
                if isinstance(result, unicode):
                    return result.encode('utf-8', 'replace')
            except Exception:
                # If anything goes wrong, return the original result
                return result
        return result
    return wrapped

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        import importlib.metadata as _metadata
        # Try to use the current package name; if not available, fallback to the module name.
        pkg_name = __package__ or __name__
        version = _metadata.version(pkg_name)
    except Exception:
        version = "unknown"
    short = version.split('.')[0] if isinstance(version, str) else "0"
    return {"full": version, "short": short}

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Basic validation of 'pieces'
    if isinstance(pieces, dict):
        pieces_iter = None
    else:
        try:
            iter(pieces)
            pieces_iter = pieces
        except TypeError:
            raise ValueError("pieces must be an iterable or a mapping")

    if style == "semver":
        # Expected keys: major, minor, patch (optional), pre (optional), build (optional)
        if not isinstance(pieces, dict):
            raise ValueError("semver style requires pieces to be a mapping with keys")
        try:
            major = int(pieces["major"])
            minor = int(pieces["minor"])
        except KeyError as e:
            raise ValueError(f"Missing required key for semver: {e.args[0]}")
        patch = int(pieces.get("patch", 0))
        version = f"{major}.{minor}.{patch}"
        if "pre" in pieces:
            pre = str(pieces["pre"])
            if pre:
                version += f"-{pre}"
        if "build" in pieces:
            build = str(pieces["build"])
            if build:
                version += f"+{build}"
        return version

    if style == "date":
        # Expected keys: year, month, day, hour (optional), minute (optional)
        if not isinstance(pieces, dict):
            raise ValueError("date style requires pieces to be a mapping with keys")
        try:
            year = int(pieces["year"])
            month = int(pieces["month"])
            day = int(pieces["day"])
        except KeyError as e:
            raise ValueError(f"Missing required key for date: {e.args[0]}")
        date_part = f"{year:04d}-{month:02d}-{day:02d}"
        hour = pieces.get("hour")
        minute = pieces.get("minute")
        if hour is not None or minute is not None:
            hour = int(hour) if hour is not None else 0
            minute = int(minute) if minute is not None else 0
            time_part = f"{hour:02d}:{minute:02d}"
            return f"{date_part} {time_part}"
        return date_part

    # Default/simple style: join the pieces with '.' using string conversion.
    if pieces_iter is None:
        # pieces was a dict; use values without guaranteed order
        pieces_iter = pieces.values()
    result_parts = [str(part) for part in pieces_iter if part is not None and str(part) != ""]
    return ".".join(result_parts) if result_parts else ""

def plus_or_dot(pieces):
    """Return a '+' if we don't already have one, else return a '.'."""
    try:
        # Use any to efficiently check for presence of '+'
        if any(p == '+' for p in pieces):
            return '.'
        return '+'
    except TypeError as exc:
        # If pieces is not iterable, raise a clear error
        raise TypeError("pieces must be an iterable") from exc
    except Exception as exc:
        # Catch any unforeseen errors to prevent the function from crashing silently
        raise RuntimeError("An unexpected error occurred in plus_or_dot") from exc

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import shlex
    # Build command list
    if isinstance(commands, (list, tuple)):
        cmd = list(commands)
    elif isinstance(commands, str):
        cmd = shlex.split(commands)
    else:
        raise ValueError("commands must be a string or an iterable of strings")
    if not cmd:
        raise ValueError("no command specified")
    # Append arguments
    if args:
        if isinstance(args, (list, tuple)):
            cmd.extend(args)
        elif isinstance(args, str):
            cmd.extend(shlex.split(args))
        else:
            raise ValueError("args must be a string or an iterable of strings")
    # Verbose output
    if verbose:
        print("Running command:", ' '.join(shlex.quote(arg) for arg in cmd))
    # Run the command
    try:
        stderr_target = subprocess.PIPE if not hide_stderr else subprocess.DEVNULL
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr_target,
            text=True
        )
        stdout = result.stdout
        stderr = result.stderr if not hide_stderr else None
        return result.returncode, stdout, stderr
    except Exception as exc:
        # Return error code and the exception message
        return -1, "", str(exc)

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        (num_objects, good_objects)

        num_objects   - number of objects (files) checked
        good_objects  - number of objects that passed all active validity checks
    """
    import os
    import hashlib

    # Determine the root directory - allow for multiple naming conventions
    root_dir = getattr(self, "root_path", None) or getattr(self, "root", None) or getattr(self, "base_path", None) or "."
    if not os.path.isdir(root_dir):
        raise ValueError(f"Root path '{root_dir}' is not a directory or does not exist")

    num_objects = 0
    good_objects = 0

    for dirpath, _, filenames in os.walk(root_dir):
        for fname in filenames:
            # Skip digest files themselves
            if fname.endswith(".sha256"):
                continue

            file_path = os.path.join(dirpath, fname)
            num_objects += 1
            valid = True

            if validate_objects:
                try:
                    with open(file_path, "rb") as f:
                        # Simply read to force any I/O errors
                        f.read()
                except Exception as exc:
                    valid = False
                    if show_warnings:
                        print(f"Warning: cannot validate file '{file_path}': {exc}")

            if check_digests:
                digest_path = file_path + ".sha256"
                if os.path.isfile(digest_path):
                    try:
                        with open(digest_path, "r") as df:
                            expected_digest = df.read().strip().lower()
                        # Compute actual digest
                        h = hashlib.sha256()
                        with open(file_path, "rb") as f:
                            for chunk in iter(lambda: f.read(8192), b""):
                                h.update(chunk)
                        actual_digest = h.hexdigest().lower()
                        if actual_digest != expected_digest:
                            valid = False
                            if show_warnings:
                                print(f"Warning: digest mismatch for '{file_path}'. "
                                      f"Expected {expected_digest}, got {actual_digest}")
                    except Exception as exc:
                        valid = False
                        if show_warnings:
                            print(f"Warning: error reading digest for '{file_path}': {exc}")

            if valid:
                good_objects += 1

    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    v = version.strip()
    if not v.isdigit():
        raise ValueError("version must be a numeric string")
    try:
        new_val = int(v) + 1
    except Exception as exc:
        raise ValueError("could not compute next version") from exc
    if v and v[0] == '0':
        # Preserve original width of leading zeros
        width = len(v)
        return str(new_val).zfill(width)
    return str(new_val)

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root (contains ``0=repo.namaste``)
        'object' - looks like an OCFL Object (contains a ``0=`` Namaste file but not ``repo``)
        'file'   - a file (any file that is not a Namaste file or a directory)
        other string explains an error description
    """
    import os, re

    try:
        if not os.path.exists(path):
            return f"error: path does not exist"
        if os.path.isfile(path):
            return 'file'

        if os.path.isdir(path):
            # List files directly inside the directory (not recursive)
            entries = os.listdir(path)
            namaste_files = [e for e in entries if e.startswith('0=') and e.endswith('.namaste')]
            if not namaste_files:
                # No Namaste file found – could still be a file but not a directory
                return f"error: no Namaste file found in directory {path}"
            # Check for repo namaste
            for nf in namaste_files:
                if re.search(r'repo\.namaste$', nf):
                    return 'root'
            # Otherwise assume it's an object
            return 'object'

        return f"error: path type not recognized"
    except Exception as exc:
        return f"error: {exc}"

def deep_merge_nodes(nodes):
    '''
    Deeply merge a list of ruamel.yaml node pairs, handling duplicate keys
    whose values are MappingNodes by recursively merging their contents.
    Non-MappingNode values are overwritten by the last one seen.
    '''
    # Helper to determine whether a node is a MappingNode
    def _is_mapping_node(node):
        return hasattr(node, 'tag') and node.tag == 'tag:yaml.org,2002:map'

    # Recursive merge of two node values
    def _merge_values(v1, v2):
        if _is_mapping_node(v1) and _is_mapping_node(v2):
            try:
                # v1 and v2 have a .value attribute containing a list of key/value pairs
                merged_pairs = deep_merge_nodes(v1.value + v2.value)
                # Preserve the constructor type of the first MappingNode
                return type(v1)(tag=v1.tag, value=merged_pairs)
            except Exception:
                # Fallback: pick the second value if merging fails
                return v2
        else:
            # Non-mapping values: last one wins
            return v2

    if not isinstance(nodes, (list, tuple)):
        return []

    merged_map = {}

def parser_flags(parser):
    '''Given an argparse.ArgumentParser instance, return its argument flags in a space-separated string.'''
    try:
        # Ensure the passed object has the expected structure
        actions = getattr(parser, "_actions", None)
        if actions is None:
            raise TypeError("The provided object does not appear to be an argparse.ArgumentParser instance.")
        flags = []
        for action in actions:
            # Each action has an option_strings attribute listing its flags
            opts = getattr(action, "option_strings", None)
            if opts:
                flags.extend(opts)
        return " ".join(flags)
    except Exception:
        # In case of any unexpected error, return an empty string
        return ""

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This
    allows common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Guard against missing subparsers
    if not subparsers:
        return {}, list(unparsed_arguments)

    parsed_map = {}
    remaining_lists = []

    for name, parser in subparsers.items():
        try:
            ns, remaining = parser.parse_known_args(unparsed_arguments)
            parsed_map[name] = ns
        except SystemExit:
            # If parsing fails, treat as no args claimed by this subparser
            parsed_map[name] = None
            remaining = list(unparsed_arguments)
        remaining_lists.append(remaining)

    # Compute arguments not claimed by any subparser (intersection of all remaining lists)
    if remaining_lists:
        common_remaining_set = set(remaining_lists[0])
        for rem in remaining_lists[1:]:
            common_remaining_set.intersection_update(rem)
        # Preserve original order
        remaining_args = [arg for arg in unparsed_arguments if arg in common_remaining_set]
    else:
        remaining_args = list(unparsed_arguments)

    return parsed_map, remaining_args

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    # Helper function to determine if a node is a MappingNode
    def is_mapping(node):
        try:
            return getattr(node, 'tag', None) == 'tag:yaml.org,2002:map'
        except Exception:
            return False

    # Recursively merge two MappingNodes into a new MappingNode
    def merge_mapping_nodes(node1, node2):
        # Extract the list of key-value pairs from each mapping node
        pairs1 = getattr(node1, 'value', [])
        pairs2 = getattr(node2, 'value', [])

        # Build a dictionary from name to index for the first mapping
        index_by_key = {}
        for idx, (k, v) in enumerate(pairs1):
            try:
                key_val = getattr(k, 'value', None)
                if key_val is not None:
                    index_by_key[key_val] = idx
            except Exception:
                continue

        # Create a mutable copy of pairs1
        merged_pairs = list(pairs1)

        # Process entries from node2
        for k2, v2 in pairs2:
            try:
                key_val2 = getattr(k2, 'value', None)
            except Exception:
                continue
            if key_val2 is None:
                continue

            if key_val2 in index_by_key:
                idx = index_by_key[key_val2]
                v1 = merged_pairs[idx][1]
                # If both values are mapping nodes, merge recursively
                if is_mapping(v1) and is_mapping(v2):
                    merged_value = merge_mapping_nodes(v1, v2)
                else:
                    merged_value = v2
                merged_pairs[idx] = (k2, merged_value)
            else:
                # New key, append at end
                merged_pairs.append((k2, v2))

        # Construct a new MappingNode with same tag as the first node
        try:
            new_tag = getattr(node1, 'tag', None) or getattr(node2, 'tag', None)
        except Exception:
            new_tag = None
        # Create a new MappingNode instance (assume constructor accepts tag and value)
        return type(node1)(new_tag, merged_pairs)

    result = []
    seen_keys = {}

    for key_node, value_node in nodes:
        try:
            key = getattr(key_node, 'value', None)
        except Exception:
            key = None
        if key is None:
            # Cannot hash; just append
            result.append((key_node, value_node))
            continue

        if key in seen_keys:
            # Merge with existing entry
            idx = seen_keys[key]
            _, existing_value = result[idx]
            if is_mapping(existing_value) and is_mapping(value_node):
                merged_value = merge_mapping_nodes(existing_value, value_node)
            else:
                # Last one wins
                merged_value = value_node
            result[idx] = (key_node, merged_value)
        else:
            # New key
            seen_keys[key] = len(result)
            result.append((key_node, value_node))

    return result

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Import here to keep the module free of imports and handle unexpected usage
    import argparse
    try:
        if not isinstance(parser, argparse.ArgumentParser):
            raise TypeError('parser must be an argparse.ArgumentParser instance')
        flags = []
        for action in parser._actions:
            # action.option_strings holds the flags for optional arguments; ignore if empty
            flags.extend(action.option_strings)
        # Return a space-separated string of distinct flags; empty if none
        return ' '.join(sorted(set(flags)))
    except Exception as e:
        raise RuntimeError(f'Error retrieving parser flags: {e}') from e

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate input types and values
    if not isinstance(response, (list, tuple)):
        raise TypeError(f"response must be a list or tuple, got {type(response).__name__}")
    if not isinstance(max_results, int) or max_results <= 0:
        raise ValueError(f"max_results must be a positive integer, got {max_results!r}")

    # Yield slices of the list in pages of size max_results
    try:
        for start in range(0, len(response), max_results):
            yield response[start:start + max_results]
    except Exception as exc:
        # Catch any runtime errors during iteration and re-raise
        raise RuntimeError(f"Error during paging: {exc}") from exc

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise TypeError('The argument `dicts` cannot be None')
    result = {}
    try:
        for d in dicts:
            if not isinstance(d, dict):
                raise TypeError(f'Expected dict, got {type(d).__name__}')
            for key, value in d.items():
                if key in result:
                    try:
                        result[key] += value
                    except Exception as exc:
                        raise TypeError(f'Cannot add values for key {key!r}') from exc
                else:
                    result[key] = value
    except TypeError:
        raise
    except Exception as exc:
        raise RuntimeError(f'Error processing input dictionaries: {exc}') from exc
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if not url_args:
        return url
    if not isinstance(url_args, dict):
        raise TypeError("url_args must be a dictionary")

    import re

    # Replace {key} style placeholders
    def replace_brace(match):
        key = match.group(1)
        if key in url_args:
            return str(url_args[key])
        raise KeyError(f"Missing URL argument: {key}")

    try:
        url = re.sub(r'\{([^}]+)\}', replace_brace, url)
    except re.error:
        # If regex fails, just return original url
        pass

    # Replace :key style placeholders
    def replace_colon(match):
        key = match.group(1)
        return str(url_args.get(key, match.group(0)))

    url = re.sub(r':([^/:\?]+)', replace_colon, url)
    return url

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    try:
        if not isinstance(val, str):
            return False
        stripped = val.strip()
        if stripped == "":
            return False
        lowered = stripped.lower()
        return lowered in {"none", "null", "nil", "n/a", "na", "nan", "undefined"}
    except Exception:
        return False

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated string.
    Handles invalid input gracefully by returning an empty string.
    """
    try:
        flags_list = []
        # Argparse stores actions in the _actions attribute; each action may have option_strings
        for action in getattr(parser, "_actions", []):
            if isinstance(action, type(parser._get_positional_actions())):  # positional actions have no option_strings
                continue
            option_strings = getattr(action, "option_strings", [])
            if option_strings:
                flags_list.extend(option_strings)
        return " ".join(flags_list)
    except Exception:
        return ""

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate alphabet
    base = len(alphabet)
    if base <= 1:
        raise ValueError("Alphabet must contain at least two distinct symbols for base conversion.")
    # Validate padding
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError("Padding must be an integer or None.")
        if padding < 0:
            raise ValueError("Padding must be non-negative.")
    # Handle negative numbers
    negative = number < 0
    n = abs(number)
    # Convert to given base
    if n == 0:
        result = alphabet[0]
    else:
        digits = []
        try:
            while n:
                n, rem = divmod(n, base)
                digits.append(alphabet[rem])
        except Exception as exc:
            raise ValueError(f"Error during conversion: {exc}") from exc
        digits.reverse()
        result = "".join(digits)
    if negative:
        result = "-" + result
    # Apply padding if requested
    if padding is not None:
        total_length = len(result)
        if negative:
            # Do not pad the negative sign
            total_length -= 1
        if total_length < padding:
            pad = alphabet[0] * (padding - total_length)
            if negative:
                result = "-" + pad + result[1:]
            else:
                result = pad + result
    return result

def replace_dots(value, arg):
    """Replaces all occurrences of '.' with the provided replacement string from the given string."""
    # Validate input types
    if not isinstance(value, str):
        raise TypeError(f"value must be a string, got {type(value).__name__}")
    if not isinstance(arg, str):
        raise TypeError(f"arg must be a string, got {type(arg).__name__}")
    try:
        return value.replace('.', arg)
    except Exception as e:
        # Re-raise a concise, descriptive error for unexpected issues
        raise RuntimeError(f"Error replacing dots: {e}") from e

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("Expected a class type for 'cls', got %r" % type(cls))
    found = set()
    try:
        for sub in cls.__subclasses__():
            found.add(sub)
            found.update(subclasses(sub))
    except Exception as exc:
        # If an error occurs while exploring subclasses, raise a descriptive error
        raise RuntimeError(f"Error while retrieving subclasses of {cls}: {exc}") from exc
    return found

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Basic validation
    if string is None:
        raise TypeError("Input string must not be None.")
    if alphabet is None:
        raise TypeError("Alphabet must not be None.")

    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two distinct symbols to represent a base.")

    # Build a mapping from symbol to its numerical value
    try:
        mapping = {symbol: idx for idx, symbol in enumerate(alphabet)}
    except Exception as exc:
        raise ValueError("Failed to construct mapping from alphabet.") from exc

    value = 0
    for idx, char in enumerate(string):
        if char not in mapping:
            raise ValueError(f"Character '{char}' at position {idx} is not present in the alphabet.")
        digit = mapping[char]
        # Multiply by base to shift left and add new digit
        value = value * base + digit

    return value

def os_is_mac():
    """
    Checks if the OS is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        import sys
        # Primary check: platform string
        if getattr(sys, "platform", "").lower() == "darwin":
            return True
        # Fallback check using os.uname() if available
        if hasattr(os, "uname"):
            uname_result = os.uname()
            if hasattr(uname_result, "sysname") and uname_result.sysname.lower() == "darwin":
                return True
    except Exception:
        # In case of any unexpected error, treat as non-mac
        pass
    return False

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.
    """
    # Helper to transform a glob-like string into a regex pattern
    def glob_to_regex(glob):
        # Use a list for efficient concatenation
        pattern = ['^']
        for char in glob:
            if char == '*':
                pattern.append('.*')
            elif char == '?':
                pattern.append('.')
            else:
                # Escape regex special characters
                if char in ".^$+{}[]|\\()":
                    pattern.append('\\' + char)
                else:
                    pattern.append(char)
        pattern.append('$')
        return ''.join(pattern)

    if not isinstance(item, dict):
        raise TypeError("input must be a dict")
    result = {}
    for key, value in item.items():
        if isinstance(key, str):
            try:
                new_key = glob_to_regex(key)
            except Exception:
                # In case of unexpected errors during pattern conversion,
                # keep the original key.
                new_key = key
        else:
            # Non-string keys are kept unchanged
            new_key = key
        result[new_key] = value
    return result

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("Input must be a string")
    # If the string is empty, return it unchanged
    if not name:
        return name
    # Remove matching surrounding quotes
    if name[0] in ("'", '"') and name[-1] == name[0]:
        return name[1:-1]
    # Remove a stray quote at the beginning or end
    if name[0] in ("'", '"'):
        name = name[1:]
    if name and name[-1] in ("'", '"'):
        name = name[:-1]
    return name

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re, sys

    if not isinstance(s, (str, bytes)):
        raise TypeError(f"split() argument must be a string, not {type(s).__name__}")
    if isinstance(s, bytes):
        s = s.decode('utf-8', errors='surrogateescape')

    # Determine platform
    if platform == 'this':
        platform = sys.platform.startswith('win')
    elif platform == 0 or (isinstance(platform, str) and platform.lower() == '0'):
        platform = True
    elif platform == 1 or (isinstance(platform, str) and platform.lower() == '1'):
        platform = False
    elif isinstance(platform, str) and platform.lower() in ('win', 'windows'):
        platform = True
    elif isinstance(platform, str) and platform.lower() in ('posix', 'unix'):
        platform = False
    else:
        raise ValueError(f"Unsupported platform specifier: {platform!r}")

    tokens = []
    i = 0
    length = len(s)
    WHITESPACE_RE = re.compile(r'\s')
    # Helper functions
    def add_token(tok):
        if tok or not tokens:
            tokens.append(tok)

    if not platform:  # POSIX
        in_single = False
        in_double = False
        escaped = False
        current = []
        while i < length:
            ch = s[i]
            if escaped:
                current.append(ch)
                escaped = False
            elif ch == '\\':
                # Escape next char
                escaped = True
            elif ch == '"' and not in_single:
                in_double = not in_double
            elif ch == "'" and not in_double:
                in_single = not in_single
            elif ch.isspace() and not in_single and not in_double:
                add_token(''.join(current))
                current = []
            else:
                current.append(ch)
            i += 1
        if escaped:
            # Trailing backslash escapes nothing -> include it literally
            current.append('\\')
        if in_single or in_double:
            raise ValueError("unterminated quote in input")
        add_token(''.join(current))
        return tokens

    else:  # Windows/CMD
        in_double = False
        current = []
        while i < length:
            ch = s[i]
            if ch.isspace() and not in_double:
                add_token(''.join(current))
                current = []
            elif ch == '"':
                # Count preceding backslashes
                backslashes = 0
                j = i - 1
                while j >= 0 and s[j] == '\\':
                    backslashes += 1
                    j -= 1
                if backslashes % 2 == 0:
                    # Even number of backslashes -> quote toggles
                    in_double = not in_double
                    # Remove all preceding backslashes that were part of escape handling
                    current = current[:len(current)-backslashes]
                    i += 1
                    continue
                else:
                    # Odd number -> last backslash is escape
                    current.append('\\')
                    # Remaining backslashes already in current
                # fall through to add quote
                current.append('"' if in_double else '"')
            else:
                current.append(ch)
            i += 1
        add_token(''.join(current))
        # Remove outer quotes if present
        final_tokens = []
        for token in tokens:
            if len(token) >= 2 and token[0] == '"' and token[-1] == '"':
                final_tokens.append(token[1:-1])
            else:
                final_tokens.append(token)
        return final_tokens

def addignored(ignored):
    '''Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        result = subprocess.run(
            ['git', 'ls-files', '-i', '--exclude-standard'],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=True
        )
    except (subprocess.CalledProcessError, FileNotFoundError):
        return ''
    files = [line.strip() for line in result.stdout.splitlines() if line.strip()]
    files.sort()
    return ','.join(files)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    # Handle None or 'always'
    if frequency is None:
        return None
    if isinstance(frequency, str) and frequency.strip().lower() == 'always':
        return None
    if not isinstance(frequency, str):
        raise ValueError('frequency must be a string')
    s = frequency.strip()
    if not s:
        raise ValueError('empty frequency string')

    import re
    match = re.match(r'^(\d+(?:\.\d+)?)\s*([a-zA-Z]+)$', s)
    if not match:
        raise ValueError(f'cannot parse frequency: {frequency}')
    number_str, unit = match.groups()
    try:
        number = float(number_str)
    except ValueError:
        raise ValueError(f'cannot parse number in frequency: {frequency}')

    unit = unit.lower()
    unit_map = {
        'days': 'days', 'day': 'days', 'd': 'days',
        'weeks': 'weeks', 'week': 'weeks', 'w': 'weeks',
        'hours': 'hours', 'hour': 'hours', 'h': 'hours',
        'minutes': 'minutes', 'minute': 'minutes', 'min': 'minutes', 'm': 'minutes',
        'seconds': 'seconds', 'second': 'seconds', 's': 'seconds',
    }
    if unit not in unit_map:
        raise ValueError(f'unknown time unit in frequency: {frequency}')

    kwargs = {unit_map[unit]: number}
    return datetime.timedelta(**kwargs)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host or not isinstance(host, str):
        return False
    host = host.strip()
    # Direct localhost checks
    if host.lower() == 'localhost':
        return True
    local_addresses = {'127.0.0.1', '::1'}
    try:
        # Include all addresses associated with this machine
        local_host = socket.gethostname()
        for addr in socket.getaddrinfo(local_host, None):
            local_addresses.add(addr[4][0])
    except Exception:
        # If any error occurs, fallback to the two loopback addresses
        pass
    # If the host string itself is a loopback address, return True
    if host in local_addresses:
        return True
    # Try resolving the host and see if any resolved address is a loopback
    try:
        for resolved in socket.getaddrinfo(host, None):
            if resolved[4][0] in local_addresses:
                return True
    except Exception:
        # If resolution fails (e.g., unknown host), treat as not local
        return False
    return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    import os
    # Validate input types
    if not isinstance(config_filename, str):
        raise TypeError("config_filename must be a string")
    if not isinstance(rendered_config, str):
        raise TypeError("rendered_config must be a string")
    if not isinstance(mode, int):
        raise TypeError("mode must be an integer")
    if not isinstance(overwrite, bool):
        raise TypeError("overwrite must be a bool")

    # Ensure target directory exists
    dir_path = os.path.dirname(os.path.abspath(config_filename))
    if dir_path and not os.path.exists(dir_path):
        try:
            os.makedirs(dir_path, exist_ok=True)
        except OSError as e:
            raise RuntimeError(f"Failed to create directories for '{config_filename}': {e}") from e

    # Check for existing file when overwrite is not allowed
    if os.path.exists(config_filename) and not overwrite:
        raise FileExistsError(f"File '{config_filename}' already exists and overwrite is set to False")

    # Write the configuration content
    try:
        with open(config_filename, 'w', encoding='utf-8') as f:
            f.write(rendered_config)
        os.chmod(config_filename, mode)
    except OSError as e:
        raise RuntimeError(f"Failed to write configuration to '{config_filename}': {e}") from e

    return config_filename

def oneline(script, seperator=" && "):
    """
    converts a script to one line command.
    This is useful to run a single ssh command and pass a one line script.

    :param script: either a multiline string or a list of strings/commands
    :param seperator: string used to join non-empty lines, default is ' && '
    :return: single line string containing the non-empty commands joined by the separator
    """
    if script is None:
        return ""
    # Accept list-like inputs as an alternative to a multiline string
    if isinstance(script, (list, tuple)):
        lines = [str(line).strip() for line in script if str(line).strip()]
    elif isinstance(script, str):
        lines = [line.strip() for line in script.splitlines() if line.strip()]
    else:
        raise TypeError("script must be a str, list, or tuple of strings")

    return seperator.join(lines)

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Validate matcher
    if matcher is None:
        raise ValueError("matcher cannot be None")
    # Convert matcher to a tuple for uniformity
    try:
        matcher = tuple(matcher)
    except Exception:
        # If matcher is not iterable, treat it as a single name
        matcher = (matcher,)
    if len(matcher) == 0:
        raise ValueError("matcher must contain at least one element (the environment variable name)")
    if len(matcher) > 2:
        raise ValueError("matcher can contain at most two elements (name, default)")
    # Extract name and optional default
    name = matcher[0]
    default = matcher[1] if len(matcher) == 2 else None
    if not isinstance(name, str):
        raise TypeError(f"name must be a string, got {type(name).__name__}")
    # Resolve environment variable
    try:
        value = os.environ[name]
        if value == '':
            # Treat empty string as defined; return it
            return value
        return value
    except KeyError:
        if default is not None:
            return default
        raise KeyError(f"Environment variable '{name}' is not defined and no default value was provided")
    except Exception as e:
        # Re-raise any other exception as a generic RuntimeError with context
        raise RuntimeError(f"Failed to resolve environment variable '{name}': {e}") from e

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    try:
        if pattern is None:
            raise ValueError("pattern cannot be None")
        if not isinstance(pattern, str):
            raise TypeError("pattern must be a string")
        if strip:
            pattern = pattern.strip()
        # Escape all regex metacharacters
        regex_pattern = re.escape(pattern)
        return regex_pattern
    except Exception as exc:
        raise ValueError(f"Failed to convert pattern to regex: {exc}") from exc

