def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create

    Returns
    -------
    numpy.ndarray
        Array of the specified shape and dtype.
    """
    # Validate `shape`
    if not isinstance(shape, (tuple, list)):
        raise TypeError(f"shape must be a tuple or list of integers, got {type(shape).__name__}")
    if len(shape) == 0:
        # Allow a 0-dimensional shape as a tuple of length 0
        shape_tuple = ()
    else:
        try:
            shape_tuple = tuple(int(dim) for dim in shape)
        except Exception as exc:
            raise TypeError(f"all elements of shape must be integers, got {shape}") from exc

    # Validate shape dimensions
    for idx, dim in enumerate(shape_tuple):
        if not isinstance(dim, int):
            raise TypeError(f"shape dimension at index {idx} is not an integer: {dim!r}")
        if dim < 0:
            raise ValueError(f"shape dimension at index {idx} is negative: {dim}")

    # Validate dtype
    try:
        dtype_obj = np.dtype(dtype)
    except Exception as exc:
        raise TypeError(f"dtype must be a valid NumPy dtype or convertible, got {dtype!r}") from exc

    # Create the array
    try:
        arr = np.empty(shape_tuple, dtype=dtype_obj)
    except Exception as exc:
        raise RuntimeError(f"Failed to create array with shape {shape_tuple} and dtype {dtype_obj}") from exc

    return arr

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8. 
    """
    if isinstance(obj, str):
        return obj.encode('utf-8')
    return obj

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """
    Return a dictionary of available Bolt protocol handlers, keyed by version tuple.
    If an explicit protocol version is provided, the dictionary will contain
    either zero or one items, depending on whether that version is supported.
    If no protocol version is provided, all available versions will be returned.
    Raises TypeError if protocol_version is not a tuple.
    """
    # Grab the mapping of supported protocols that the subclass should
    # provide; use an empty dict as a safe default.
    try:
        supported = getattr(cls, "_SUPPORTED_PROTOCOLS", {})
    except Exception:
        supported = {}

    # Validate explicit protocol_version input.
    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple")
        # Return a single-item dict if the handler exists, otherwise empty.
        handler = supported.get(protocol_version)
        return {protocol_version: handler} if handler else {}

    # Return all supported protocol handlers
    return dict(supported)

@classmethod
def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    This method provides a convenient way to instantiate a ``Bookmarks`` object
    from an iterable of raw bookmark strings.  The implementation is tolerant
    to a variety of ``values`` inputs and performs basic validation.  If
    ``values`` is ``None`` or an empty iterable an empty ``Bookmarks`` instance
    is returned.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    :return: A populated :class:`Bookmarks` instance
    :raises ValueError: If any element in ``values`` is not a string.
    """
    # Instantiate a new instance of the calling class; allow ``__new__`` to
    # create the object even if ``__init__`` requires no arguments.
    try:
        instance = cls()
    except TypeError as exc:
        # Handle classes that only allow keyword args or a different signature
        try:
            instance = cls.__new__(cls)
        except Exception:
            raise TypeError(
                f"Could not instantiate {cls.__name__} with arguments: {exc}"
            )
        else:
            # If __init__ requires arguments, attempt to call with defaults
            try:
                init_sig = instance.__init__
                init_sig(None)  # type: ignore
            except TypeError:
                # skip; the instance is shippable as is
                pass

    # Store internal representation: if the class already has a ``bookmarks``
    # attribute, preserve it; otherwise create a fresh list.
    if hasattr(instance, "bookmarks"):
        storage = instance.bookmarks
        if not isinstance(storage, list):
            # If the existing type isn't list, replace it with a list
            storage = []
            instance.bookmarks = storage
    else:
        storage = []
        setattr(instance, "bookmarks", storage)

    # Validate input and fill the storage
    if values is None:
        return instance

    if not hasattr(values, "__iter__"):
        raise ValueError("``values`` must be an iterable of strings")

    for raw in values:
        if not isinstance(raw, str):
            raise ValueError(
                f"Bookmark raw value must be a string, got {type(raw).__name__}"
            )
        # Strip surrounding whitespace if desired
        cleaned = raw.strip()
        storage.append(cleaned)

    return instance

def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised."""
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    del self[key]
    return value

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    try:
        # Assume the class uses a dummy head and tail to maintain a doubly‑linked list.
        # `self.tail.prev` should be the least recently used node.
        lru_node = getattr(self, "tail", None)
        if lru_node is None or getattr(lru_node, "prev", None) is None:
            raise RuntimeError("No tail or prev node available; cannot pop.")

        lru = lru_node.prev
        # If the list is empty, the prev of tail will point back to the head sentinel.
        if getattr(lru, "key", None) is None and getattr(lru, "val", None) is None:
            raise KeyError("Pop from an empty cache")

        # unlink the node from the list
        prev_node = lru.prev
        if prev_node is None:
            raise RuntimeError("Corrupted list structure before pop")

        prev_node.next = lru_node
        lru_node.prev = prev_node

        # remove from the mapping dict
        cache_map = getattr(self, "cache", {})
        key = lru.key
        value = lru.val
        if key in cache_map:
            del cache_map[key]
        else:
            # Inconsistent state – still try to return the key/value
            pass

        # adjust size counter if present
        if hasattr(self, "size"):
            try:
                self.size -= 1
            except Exception:
                pass

        return (key, value)

    except KeyError as ke:
        # propagate key errors strictly
        raise ke
    except Exception as e:
        # For any other unforeseen errors, provide a clear message
        raise RuntimeError(f"Failed to pop least recently used item: {e}")

def popitem(self):
    """
    Remove and return the (key, value) pair most recently used.
    """
    # Attempt to retrieve the underlying data container.
    # It may be a private attribute `_data` or the instance itself.
    container = getattr(self, "_data", None)
    if container is None:
        container = self

    # Try popping the most recent item. Different containers have slightly
    # different APIs, so we fall back gracefully.
    try:
        # OrderedDict and compatible containers accept `last=True`.
        return container.popitem(last=True)
    except TypeError:
        # If the container's popitem doesn't accept `last`, use the default
        # popitem which, for ordered containers, removes the last entry.
        try:
            return container.popitem()
        except KeyError:
            raise KeyError("Cannot pop item from an empty structure.")
    except AttributeError:
        raise AttributeError("Underlying container does not support popitem.")
    except Exception as exc:
        # Unexpected runtime errors are propagated with a clear message.
        raise RuntimeError(f"Failed to pop an item: {exc}") from exc

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    if not isinstance(self, dict):
        raise TypeError('popitem() requires a dict instance')
    if not self:
        raise KeyError('dictionary is empty')
    try:
        import random
        key = random.choice(list(self.keys()))
        value = self.pop(key)
        return (key, value)
    except Exception as exc:
        raise RuntimeError(f'Error in popitem: {exc}') from exc

def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    # The regex is designed to match the keyword "in" as a standalone word,
    # which is commonly used to denote input parameters in signatures.
    # It includes word boundaries to avoid matching substrings inside other words.
    try:
        return re.compile(r'\b(in)\b')
    except re.error as exc:
        # In practice this should never fail, but guard against malformed regexes.
        raise RuntimeError("Failed to compile the in‑style parameter regex.") from exc

