def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        if request is None:
            return False

        # Check for a public message
        if hasattr(request, "is_public"):
            try:
                if request.is_public():
                    return True
            except Exception:
                pass

        # Check for a private message
        if hasattr(request, "is_private"):
            try:
                if request.is_private():
                    return True
            except Exception:
                pass

        # Check for legacy payload structure
        if hasattr(request, "payload"):
            payload = request.payload
            if isinstance(payload, dict):
                # Example legacy indicators – adjust as needed for real schema
                legacy_keys = {"legacy", "old_payload", "old_format"}
                if legacy_keys & payload.keys():
                    return True
                # Nested legacy indicators
                if any(
                    isinstance(val, dict) and legacy_keys & val.keys()
                    for val in payload.values()
                ):
                    return True

    except Exception:
        # Any unexpected error results in a negative identification
        return False

    return False

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        raise ValueError("node cannot be None")
    # Ensure node looks like an ElementTree element
    if not hasattr(node, 'tag'):
        raise TypeError("node must be an XML element with a 'tag' attribute")
    # Elements are iterable over their children
    try:
        iterator = iter(node)
    except TypeError:
        # node is not iterable
        raise TypeError("node must be an iterable XML element (e.g., ElementTree.Element)")
    result = {}
    for child in iterator:
        # Skip non-element children (e.g., text nodes)
        if not hasattr(child, 'tag'):
            continue
        result[child.tag] = child
    return result

