def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    # Validate input
    if not isinstance(handle, str):
        raise TypeError("handle must be a string")
    if '@' not in handle:
        raise ValueError("handle must contain '@' separating local part and domain")

    try:
        domain = handle.split('@', 1)[1]
        url = f"https://{domain}/.well-known/webfinger?resource=acct:{handle}"

        urllib_request = __import__('urllib.request')
        urllib_error = __import__('urllib.error')
        json_mod = __import__('json')

        with urllib_request.urlopen(url, timeout=10) as response:
            if getattr(response, "status", 200) != 200:
                return {}
            data = response.read().decode('utf-8')
            return json_mod.loads(data)
    except Exception:
        return {}

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from (e.g. "example.org")
    :returns: XML ElementTree element containing the host-meta data
    """
    import urllib.request
    import urllib.error
    import xml.etree.ElementTree as ET

    # Ensure correct scheme
    if not host.startswith(("http://", "https://")):
        url = "https://%s/.well-known/host-meta" % host
    else:
        # Trim any trailing slash and append well-known path
        url = host.rstrip("/") + "/.well-known/host-meta"

    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            content = response.read()
    except urllib.error.HTTPError as e:
        raise ValueError(f"HTTP error retrieving host-meta from {url}: {e.code} {e.reason}") from e
    except urllib.error.URLError as e:
        raise ValueError(f"URL error retrieving host-meta from {url}: {e.reason}") from e
    except Exception as e:
        raise ValueError(f"Unexpected error retrieving host-meta from {url}: {e}") from e

    try:
        root = ET.fromstring(content)
    except ET.ParseError as e:
        raise ValueError(f"Failed to parse host-meta XML from {url}: {e}") from e

    return root

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.request``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    # Basic validation of input arguments
    if not isinstance(url, str) or not url:
        return None, ValueError("`url` must be a non-empty string")
    if not isinstance(timeout, (int, float)) or timeout <= 0:
        return None, ValueError("`timeout` must be a positive number")
    if not isinstance(method, str):
        return None, ValueError("`method` must be a string")

    method = method.lower()

    try:
        # Use the generic request call so that any HTTP method can be used
        response = requests.request(method=method,
                                    url=url,
                                    data=data,
                                    timeout=timeout,
                                    *args, **kwargs)
        # Request succeeded, return status code and no error
        return response.status_code, None
    except Exception as exc:
        # Any exception (network, timeout, invalid data, etc.) is captured
        return None, exc

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type

    Parameters
    ----------
    settings_dirs : Union[str, Iterable[str]]
        One or more directory paths to search for files.
    spec_option : None | str | Iterable[str] | Callable[[str], bool]
        None for no filtering, a string or list of strings representing glob
        patterns, or a callable that accepts a file path and returns a boolean.
        Returns a list of file paths (as absolute strings) found in the
        directories matching the supplied specification.

    Returns
    -------
    list[str]
        List of absolute file paths that satisfy the specification.

    Raises
    ------
    ValueError
        If `spec_option` is of an unsupported type.
    """
    import os
    import fnmatch
    from collections.abc import Iterable, Callable

    # Normalise settings_dirs to an iterable of strings
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        try:
            dirs = list(settings_dirs)
        except Exception:
            raise ValueError("settings_dirs must be a string or an iterable of strings")

    # Normalise spec_option
    def matches(path: str) -> bool:
        if spec_option is None:
            return True
        if isinstance(spec_option, str):
            return fnmatch.fnmatch(os.path.basename(path), spec_option)
        if isinstance(spec_option, Iterable) and not isinstance(spec_option, (str, bytes)):
            return any(fnmatch.fnmatch(os.path.basename(path), pattern) for pattern in spec_option)
        if isinstance(spec_option, Callable):
            try:
                return bool(spec_option(path))
            except Exception:
                return False
        raise ValueError("spec_option must be None, a string, a non-string iterable of strings, or a callable")

    results = []
    for d in dirs:
        try:
            for entry in os.scandir(d):
                if entry.is_file():
                    path = os.path.abspath(entry.path)
                    if matches(path):
                        results.append(path)
        except (FileNotFoundError, PermissionError, OSError):
            # Skip directories that cannot be accessed
            continue

    # Return sorted paths for deterministic output
    return sorted(results)

@classmethod
def ansible_config_manager(cls):
    """Gets the ansible config manager. """
    import os
    config = {}
    # Determine the config file path, default to 'ansible.cfg' if none specified
    config_path = os.getenv('ANSIBLE_CONFIG', 'ansible.cfg')
    try:
        with open(config_path, 'r') as f:
            for line in f:
                line = line.strip()
                # Skip empty lines and comments
                if not line or line.startswith('#'):
                    continue
                # Parse key=value pairs
                if '=' in line:
                    key, val = line.split('=', 1)
                    config[key.strip()] = val.strip()
    except FileNotFoundError:
        # If the config file does not exist, return an empty dictionary
        return {}
    except PermissionError as e:
        raise RuntimeError(f"Permission denied while reading Ansible config '{config_path}': {e}")
    except Exception as e:
        raise RuntimeError(f"Unexpected error while reading Ansible config '{config_path}': {e}")
    return config

