@classmethod
def plugins_manager(cls):
    """Gets the plugin manager."""
    try:
        # Lazy initialization: store the manager on the class if it hasn't been created yet
        if not hasattr(cls, "_plugin_manager"):
            # Define a minimal plugin manager implementation
            class _SimplePluginManager:
                def __init__(self):
                    self._registry = {}

                def register(self, name, plugin):
                    """
                    Register a plugin under a unique string name.
                    Raises:
                        TypeError: If the name is not a string.
                        KeyError: If a plugin with the same name already exists.
                    """
                    if not isinstance(name, str):
                        raise TypeError("Plugin name must be a string")
                    if name in self._registry:
                        raise KeyError(f"Plugin '{name}' already registered")
                    self._registry[name] = plugin

                def get(self, name):
                    """
                    Retrieve a plugin by name.
                    Returns:
                        The plugin instance or None if not found.
                    """
                    return self._registry.get(name)

                def all_plugins(self):
                    """Return a copy of the plugin registry."""
                    return self._registry.copy()

            cls._plugin_manager = _SimplePluginManager()

        return cls._plugin_manager
    except Exception as exc:
        raise RuntimeError("Unable to obtain plugin manager") from exc

@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("Spec content is None")

        # Load YAML content
        try:
            data = yaml.safe_load(spec_content)
        except Exception as exc:
            raise IRValidatorException(
                f"Failed to parse spec content as YAML: {exc}"
            )

        if not isinstance(data, dict):
            raise IRValidatorException(
                f"Expected YAML mapping, got {type(data).__name__}"
            )

        # Define mandatory fields (adjust as needed)
        required_fields = ["name", "specVersion", "steps"]

        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(
                f"Spec is missing required fields: {', '.join(missing)}"
            )

        return data

@classmethod
def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    # Ensure a file path was provided
    if not yaml_file:
        raise IRValidatorException("No YAML file path provided.")

    # Load YAML safely
    try:
        import yaml
    except Exception as exc:
        raise IRValidatorException(f"Failed to import yaml module: {exc}") from exc

    try:
        with open(yaml_file, "r", encoding="utf-8") as fh:
            data = yaml.safe_load(fh)
    except FileNotFoundError as exc:
        raise IRValidatorException(f"YAML file not found: {yaml_file}") from exc
    except Exception as exc:
        raise IRValidatorException(f"Error reading YAML file '{yaml_file}': {exc}") from exc

    if not isinstance(data, dict):
        raise IRValidatorException(f"YAML file '{yaml_file}' does not contain a dictionary at the top level.")

    # Determine required fields (class attribute if defined)
    required_fields = getattr(cls, "REQUIRED_FIELDS", [])
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields in YAML file '{yaml_file}': {', '.join(missing)}")

    return data

def _include_groups(self, parser_dict):
    """
    Resolve the include dict directive in the spec files.

    The parser_dict may contain a special key '__include_groups__' whose value
    is a mapping where the key is a group name and the value is either (a) a
    path to a YAML file to be loaded for that group or (b) a dictionary
    containing the group content directly. This method loads or merges the
    content for each included group and inserts the resulting group dict
    into parser_dict under the corresponding group name. If a group already
    exists, the included content is merged into it with the included
    values overriding any duplicates.

    Parameters
    ----------
    parser_dict : dict
        Dictionary representing the parsed spec file.

    Returns
    -------
    dict
        The updated dictionary with all include groups resolved.

    Raises
    ------
    RuntimeError
        If an include path does not exist, cannot be parsed as YAML, or
        another I/O related error occurs.
    """
    # The special key for include directives
    INCLUDE_KEY = "__include_groups__"

    # Helper function to merge two dictionaries (deep merge)
    def _deep_merge(dest, src):
        for key, value in src.items():
            if (
                key in dest
                and isinstance(dest[key], dict)
                and isinstance(value, dict)
            ):
                _deep_merge(dest[key], value)
            else:
                dest[key] = value

    # Helper function to process an include entry
    def _process_include(name, entry, visited_files):
        if isinstance(entry, str):
            # entry is a file path
            path = entry
            abs_path = (
                path
                if os.path.isabs(path)
                else os.path.join(os.path.abspath(os.path.dirname(__file__)), path)
            )
            if abs_path in visited_files:
                # Avoid circular inclusion
                return {}
            visited_files.add(abs_path)
            if not os.path.exists(abs_path):
                raise RuntimeError(f"Included file '{abs_path}' does not exist.")
            try:
                with open(abs_path, "r", encoding="utf-8") as f:
                    data = yaml.safe_load(f)
            except Exception as exc:
                raise RuntimeError(f"Failed to load include file '{abs_path}': {exc}")
            # If the file defines the same group structure, use it directly
            if isinstance(data, dict):
                return data
            else:
                # Wrap non-dict content in a dict under the group name
                return {name: data}
        elif isinstance(entry, dict):
            # entry is already a dict with content
            return entry
        else:
            # Unsupported type
            raise RuntimeError(
                f"Unsupported include entry for group '{name}': {entry!r}"
            )

    # Main logic
    if not isinstance(parser_dict, dict):
        raise RuntimeError("parser_dict must be a dictionary")

    include_map = parser_dict.get(INCLUDE_KEY, {})
    if not isinstance(include_map, dict):
        raise RuntimeError(f"'{INCLUDE_KEY}' must be a dictionary if present")

    # Remove the include key to avoid reprocessing in nested merges
    parser_dict = dict(parser_dict)
    parser_dict.pop(INCLUDE_KEY, None)

    visited = set()
    for group_name, entry in include_map.items():
        try:
            included_content = _process_include(group_name, entry, visited)
        except RuntimeError as exc:
            # Propagate with context
            raise RuntimeError(f"Error including group '{group_name}': {exc}") from exc

        if group_name in parser_dict:
            if isinstance(parser_dict[group_name], dict) and isinstance(included_content, dict):
                # Merge dictionaries, included overrides
                _deep_merge(parser_dict[group_name], included_content)
            else:
                # Replace non-dict with dict
                parser_dict[group_name] = included_content
        else:
            parser_dict[group_name] = included_content

    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    try:
        # Ensure the 'spec' attribute exists and is a dictionary
        if hasattr(self, 'spec') and isinstance(self.spec, dict):
            # The spec may contain an 'arguments' key with a list of argument specs
            arguments = self.spec.get('arguments', [])
            if not isinstance(arguments, list):
                arguments = []
            for arg in arguments:
                # Each argument spec should be a dictionary
                if not isinstance(arg, dict):
                    continue
                name = arg.get('name')
                if not name:
                    continue
                # Start with the explicit default if present
                value = arg.get('default')
                # If a default is present, attempt type conversion according to the
                # optional 'type' field in the spec
                if value is not None:
                    typ = arg.get('type')
                    try:
                        if typ == 'int':
                            value = int(value)
                        elif typ == 'float':
                            value = float(value)
                        elif typ == 'bool':
                            # Accept common true/false representations when value is a string
                            if isinstance(value, str):
                                value = value.strip().lower() in ('1', 'true', 'yes', 'on', 't')
                    except Exception:
                        # If conversion fails, keep the original value
                        pass
                defaults[name] = value
    except Exception:
        # In case of any unexpected errors, return whatever defaults have been collected
        pass
    return defaults

def get_deprecated_args(self):
    """
    Returns a dictionary mapping deprecated argument names to the
    arguments they have been replaced with.  If the instance does
    not define the ``_deprecated_args`` attribute, an empty dict is
    returned.  Any unexpected error during retrieval results in an
    empty dictionary rather than propagating the exception.
    """
    try:
        return getattr(self, "_deprecated_args", {})
    except Exception:
        return {}

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """
    Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    try:
        # Ensure we have a list/ set/ tuple of deprecated keys to check
        deprecated_keys = getattr(self, "deprecated_keys", None)
        if not isinstance(deprecated_keys, (list, set, tuple)):
            return
        # Combine both argument sources
        combined_args = {}
        if isinstance(cli_args, dict):
            combined_args.update(cli_args)
        if isinstance(answer_file_args, dict):
            combined_args.update(answer_file_args)
        # Print deprecation warnings for any present keys
        for key in deprecated_keys:
            if key in combined_args:
                # Import sys lazily to avoid global imports
                import sys
                warning = (
                    f"Warning: argument '{key}' is deprecated "
                    f"and will be removed in a future release."
                )
                print(warning, file=sys.stderr)
    except Exception as err:
        # Avoid propagating errors; log to stderr instead
        import sys
        print(f"Error during deprecation validation: {err}", file=sys.stderr)

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    # Validate input types
    if not isinstance(command_name, str):
        raise TypeError(f"command_name must be a string, got {type(command_name).__name__}")
    if not isinstance(argument_name, str):
        raise TypeError(f"argument_name must be a string, got {type(argument_name).__name__}")

    # Ensure the option store exists
    if not hasattr(self, "_options") or not isinstance(self._options, dict):
        raise AttributeError("Option store '_options' not found or not a dictionary")

    try:
        # Retrieve the command's option dictionary
        command_opts = self._options[command_name]
    except KeyError as e:
        raise KeyError(f"Command '{command_name}' not found in options") from e

    # Ensure the command options are a dict
    if not isinstance(command_opts, dict):
        raise TypeError(f"Options for command '{command_name}' must be a dict, got {type(command_opts).__name__}")

    try:
        # Retrieve the specific option specification
        spec = command_opts[argument_name]
    except KeyError as e:
        raise KeyError(f"Option '{argument_name}' not found for command '{command_name}'") from e

    # Optionally validate the returned spec type if needed
    # (Assume spec is a dict or custom object; skip further validation)

    return spec

def _get_conditionally_required_args(self, command_name, options_spec,
                                       args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required_args = []

    # Ensure inputs are usable
    if not isinstance(options_spec, (list, tuple)):
        return required_args
    if not isinstance(args, dict):
        args = {}

    for opt in options_spec:
        try:
            cond = opt.get('required_when')
            if cond is None:
                continue

            matched = False
            if callable(cond):
                # If the condition is a callable, call it with the args dict
                try:
                    matched = bool(cond(args))
                except Exception:
                    matched = False
            elif isinstance(cond, str):
                # Prepare a restricted eval environment
                # expose args values as local identifiers and the args dict itself
                local_vars = {}
                for k, v in args.items():
                    if isinstance(k, str) and k.isidentifier():
                        local_vars[k] = v
                local_vars['args'] = args
                try:
                    matched = bool(eval(cond, {}, local_vars))
                except Exception:
                    matched = False
            else:
                # Unsupported condition type
                matched = False

            if matched:
                name = opt.get('fullname') or opt.get('name')
                if name:
                    required_args.append(name)
        except Exception:
            # Skip any problematic option without raising
            continue

    return required_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments. Expected to be a mapping where each
                 value is either a plain object or a tuple in the form
                 (value, max_length). If a max_length is provided, the
                 function verifies that the length of the value does not
                 exceed it.
    """
    try:
        for key, val in args.items():
            # Determine the actual value and the optional maximum length
            if isinstance(val, tuple) and len(val) == 2:
                value, max_len = val
            else:
                value, max_len = val, None

            # Validate length only if a maximum is specified
            if max_len is not None:
                # Ensure value supports length
                if not hasattr(value, "__len__"):
                    raise TypeError(f"Argument '{key}' has no length")
                if len(value) > max_len:
                    raise ValueError(
                        f"Argument '{key}' exceeds maximum length of {max_len}"
                    )
    except Exception as exc:
        # Wrap any exception in a ValueError to provide a clear error message
        raise ValueError(f"Error validating length for arguments: {exc}") from exc
    return True

