def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control, nested, and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file.
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list/dict of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    # Normalise the input to an iterable of (key, value) pairs.
    if args is None:
        return control_args, nested_args
    if hasattr(args, "items"):
        items = list(args.items())
    elif isinstance(args, (list, tuple)):
        items = []
        for elem in args:
            if isinstance(elem, tuple) and len(elem) == 2:
                items.append(elem)
            elif hasattr(elem, "key") and hasattr(elem, "value"):
                items.append((elem.key, elem.value))
    elif hasattr(args, "__dict__"):
        items = list(vars(args).items())
    else:
        # If args is a single value, we cannot process it.
        return control_args, nested_args

    for key, value in items:
        if not isinstance(key, str):
            # For non-string keys, treat them as nested.
            nested_args[key] = value
            continue
        lc_key = key.lower()
        if lc_key.startswith("control."):
            control_args[key] = value
        else:
            # All other keys are considered nested, including custom ones.
            nested_args[key] = value

    return control_args, nested_args

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``.

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of ``key=value`` strings representing extra variables
        :return: The extended dictionary
        :raises TypeError: If ``vars_dict`` is not a dictionary
        :raises RuntimeError: If any unexpected error occurs while processing
        """
        # Validate the base dictionary
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")

        # Nothing to merge
        if not extra_vars:
            return vars_dict

        try:
            for item in extra_vars:
                # Skip non-string items (they cannot be parsed as key=value)
                if not isinstance(item, str):
                    continue

                # Split only on the first '='
                if '=' not in item:
                    continue

                key, value = item.split('=', 1)
                key = key.strip()
                value = value.strip()

                # Only update if the key is non-empty
                if key:
                    vars_dict[key] = value
        except Exception as exc:
            # Wrap any unexpected exception in a RuntimeError for clarity
            raise RuntimeError(f"Error while merging extra variables: {exc}") from exc

        return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        # Retrieve type mapping for the given parser; default to empty if not defined
        type_mapping = getattr(self, "_arg_type_map", {})
        arg_types = type_mapping.get(parser_name, {})

        # Iterate over a snapshot of items so we can modify the dict safely
        for arg, val in list(values_dict.items()):
            # Skip casting if no type information or value is None
            if arg not in arg_types or val is None:
                continue

            target_type = arg_types[arg]
            try:
                if target_type is bool:
                    if isinstance(val, bool):
                        cast_value = val
                    else:
                        # Accept common truthy/falsey strings
                        if isinstance(val, str):
                            lower = val.strip().lower()
                            if lower in ("true", "1", "yes", "y"):
                                cast_value = True
                            elif lower in ("false", "0", "no", "n"):
                                cast_value = False
                            else:
                                raise ValueError
                        else:
                            cast_value = bool(val)

                elif target_type is int:
                    cast_value = int(val)

                elif target_type is float:
                    cast_value = float(val)

                elif target_type is list:
                    if isinstance(val, list):
                        cast_value = val
                    elif isinstance(val, str):
                        # Split comma‑separated strings
                        cast_value = [x.strip() for x in val.split(",") if x.strip()]
                    else:
                        cast_value = [val]

                else:
                    # Generic cast using the target type constructor
                    cast_value = target_type(val)

            except Exception as exc:
                raise ValueError(
                    f"Cannot cast argument '{arg}' with value '{val}' "
                    f"to type {target_type.__name__}"
                ) from exc

            # Update the dictionary in place
            values_dict[arg] = cast_value

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    try:
        # Dynamically import required modules to avoid top-level imports
        json = __import__('json')
        os = __import__('os')
    except Exception:
        return {}

    # Determine the possible spec file names
    spec_files = ['plugin.json', 'plugin.yaml', 'plugin.yml']
    spec_path = None
    for fname in spec_files:
        candidate = os.path.join(plugin_dir, fname)
        if os.path.isfile(candidate):
            spec_path = candidate
            break

    if not spec_path:
        return {}

    try:
        if spec_path.endswith('.json'):
            with open(spec_path, 'r', encoding='utf-8') as f:
                data = json.load(f)
        else:
            yaml = None
            try:
                yaml = __import__('yaml')
            except Exception:
                return {}
            with open(spec_path, 'r', encoding='utf-8') as f:
                data = yaml.safe_load(f)
    except Exception:
        return {}

    # Ensure we have a dictionary
    if not isinstance(data, dict):
        return {}

    def _flatten(d, parent_key=''):
        items = {}
        for k, v in d.items():
            new_key = f'{parent_key}.{k}' if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key))
            else:
                items[new_key] = v
        return items

    return _flatten(data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    try:
        env_var = 'CONFIG_PATH'
        # Only set if the environment variable is missing
        if env_var not in os.environ:
            # Prefer an attribute set on this instance; fall back silently if absent
            default_path = getattr(self, 'config_path', None)
            if default_path:
                os.environ[env_var] = default_path
    except Exception:
        # Silently ignore any failure (e.g., missing os import, permission issues)
        pass

def strip_root(path, root):
    """
    Remove root from path, throw exception on failure.
    """
    # Validate inputs
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both 'path' and 'root' must be strings")
    if root == '':
        raise ValueError("'root' cannot be an empty string")
    if path == '':
        raise ValueError("'path' cannot be an empty string")

    # Normalise trailing separators (both slash and backslash)
    def _strip_trailing_sep(p):
        while len(p) > 1 and (p.endswith('/') or p.endswith('\\')):
            p = p[:-1]
        return p

    norm_root = _strip_trailing_sep(root)
    norm_path = path  # keep the original path as we need to return the remainder

    # If the path is exactly the root, return an empty string
    if norm_path == norm_root:
        return ''

    # Attempt to strip using both common path separators
    for sep in ('/', '\\'):
        pref = norm_root + sep
        if norm_path.startswith(pref):
            return norm_path[len(pref):]

    # If no match, raise an error
    raise ValueError(f"Path '{path}' does not start with root '{root}'")
